**Q5. Write a C program using structures with array to print the three students record after accepting details like Name, PRN, Address. (7 marks)**

```c
#include <stdio.h>

struct Student {
    char name[50];
    int prn;
    char address[100];
};

int main() {
    struct Student s[3];
    for (int i = 0; i < 3; i++) {
        printf("Enter name, PRN and address for student %d:\n", i+1);
        scanf("%s %d %s", s[i].name, &s[i].prn, s[i].address);
    }

    printf("\nStudent Records:\n");
    for (int i = 0; i < 3; i++) {
        printf("Name: %s, PRN: %d, Address: %s\n", s[i].name, s[i].prn, s[i].address);
    }
    return 0;
}
```

